import json
import re
import urllib.parse
from typing import Any

from langflow.custom import Component
from langflow.io import DataInput, Output, StrInput
from langflow.schema import Data


class KumuSubgraphURL(Component):
    display_name = "Kumu Subgraph URL"
    description = "Generate a Kumu embed URL for a focused ATLAS subgraph from AML IDs."
    icon = "link"

    inputs = [
        DataInput(
            name="ids",
            display_name="ID JSON",
            info="JSON object containing an `ids` list of AML ID strings. The first ID is the anchor.",
            tool_mode=True,
            required=True,
        ),
        StrInput(
            name="project_id",
            display_name="Project ID",
        ),
        StrInput(
            name="map_name",
            display_name="Map",
            value="atlas",
            info="Name of the Kumu map view",
        ),
    ]

    outputs = [
        Output(
            name="Data",
            display_name="Results",
            method="build_url",
        )
    ]

    def _extract_payload(self, value: Any) -> dict[str, Any]:
        if isinstance(value, Data):
            return value.data

        if isinstance(value, dict):
            return value

        data = getattr(value, "data", None)
        if isinstance(data, dict):
            return data

        text = getattr(value, "text", None)
        if isinstance(text, str) and text.strip():
            value = text

        if isinstance(value, str):
            try:
                payload = json.loads(value)
            except json.JSONDecodeError as exc:
                raise ValueError("Kumu IDs JSON must be a valid JSON object.") from exc

            if isinstance(payload, dict):
                return payload

        raise ValueError("Kumu IDs must be an object containing an `ids` list.")

    def _extract_list(self, value: Any) -> list[Any]:
        if isinstance(value, list):
            return value

        if isinstance(value, str):
            stripped_value = value.strip()
            if not stripped_value:
                return []

            try:
                parsed_value = json.loads(stripped_value)
            except json.JSONDecodeError:
                return [part.strip() for part in re.split(r"[,\n]", stripped_value) if part.strip()]

            if isinstance(parsed_value, list):
                return parsed_value

            if isinstance(parsed_value, str):
                return [parsed_value]

        raise ValueError("Kumu IDs must contain an `ids` list.")

    def _normalize_ids(self, ids: Any) -> list[str]:
        if isinstance(ids, list):
            values = self._extract_list(ids)
        elif isinstance(ids, str) and not ids.strip().startswith("{"):
            values = self._extract_list(ids)
        else:
            payload = self._extract_payload(ids)
            values = self._extract_list(payload.get("ids"))

        return [str(i).strip() for i in values if str(i).strip()]

    def _build_iframe(self, url: str) -> str:
        return f"<iframe src='{url}' width='600' height='400' frameborder='0'></iframe>"

    def build_url(self) -> Data:
        ids = self._normalize_ids(self.ids)

        # Empty case
        if not ids:
            return Data(data={
                "url": "",
                "iframe": ""
            })

        anchor = ids[0].lower().replace(".", "-")

        # Single node case
        if len(ids) == 1:
            url = (
                f"https://embed.kumu.io/{self.project_id}"
                f"#{self.map_name.lower()}/{anchor}"
                f"?focus=1"
            )
            return Data(data={
                "url": url,
                "iframe": self._build_iframe(url)
            })

        # Multi-node case
        directives = [
            f"#{i.replace('.', '-')} out 1"
            for i in ids
        ]

        focus_string = ", ".join(directives)
        focus_encoded = urllib.parse.quote(focus_string, safe="")

        url = (
            f"https://embed.kumu.io/{self.project_id}"
            f"#{self.map_name.lower()}/{anchor}"
            f"?focus={focus_encoded}"
        )

        return Data(data={
            "url": url,
            "iframe": self._build_iframe(url)
        })

import ast
import operator
from collections.abc import Callable

from lfx.custom.custom_component.component import Component
from lfx.inputs.inputs import MessageTextInput
from lfx.io import Output
from lfx.schema.data import Data


class CalculatorComponent(Component):
    display_name = "Calculator"
    description = "Perform basic arithmetic operations on a given expression."
    documentation: str = "https://docs.langflow.org/calculator"
    icon = "calculator"

    # Cache operators dictionary as a class variable
    OPERATORS: dict[type[ast.operator], Callable] = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
    }

    inputs = [
        MessageTextInput(
            name="expression",
            display_name="Expression",
            info="The arithmetic expression to evaluate (e.g., '4*4*(33/22)+12-20').",
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(display_name="JSON", name="result", type_=Data, method="evaluate_expression"),
    ]

    def _eval_expr(self, node: ast.AST) -> float:
        """Evaluate an AST node recursively."""
        if isinstance(node, ast.Constant):
            if isinstance(node.value, int | float):
                return float(node.value)
            error_msg = f"Unsupported constant type: {type(node.value).__name__}"
            raise TypeError(error_msg)
        if isinstance(node, ast.Num):  # For backwards compatibility
            if isinstance(node.n, int | float):
                return float(node.n)
            error_msg = f"Unsupported number type: {type(node.n).__name__}"
            raise TypeError(error_msg)

        if isinstance(node, ast.BinOp):
            op_type = type(node.op)
            if op_type not in self.OPERATORS:
                error_msg = f"Unsupported binary operator: {op_type.__name__}"
                raise TypeError(error_msg)

            left = self._eval_expr(node.left)
            right = self._eval_expr(node.right)
            return self.OPERATORS[op_type](left, right)

        error_msg = f"Unsupported operation or expression type: {type(node).__name__}"
        raise TypeError(error_msg)

    def evaluate_expression(self) -> Data:
        """Evaluate the mathematical expression and return the result."""
        try:
            tree = ast.parse(self.expression, mode="eval")
            result = self._eval_expr(tree.body)

            formatted_result = f"{float(result):.6f}".rstrip("0").rstrip(".")
            self.log(f"Calculation result: {formatted_result}")

            self.status = formatted_result
            return Data(data={"result": formatted_result})

        except ZeroDivisionError:
            error_message = "Error: Division by zero"
            self.status = error_message
            return Data(data={"error": error_message, "input": self.expression})

        except (SyntaxError, TypeError, KeyError, ValueError, AttributeError, OverflowError) as e:
            error_message = f"Invalid expression: {e!s}"
            self.status = error_message
            return Data(data={"error": error_message, "input": self.expression})

    def build(self):
        """Return the main evaluation function."""
        return self.evaluate_expression

import ast
import json
import re
from typing import Any

import pandas as pd
from lfx.custom.custom_component.component import Component
from lfx.io import DataFrameInput, DataInput, Output, StrInput
from lfx.log.logger import logger
from lfx.schema.data import Data
from lfx.schema.dataframe import DataFrame


class DataFrameJSONFilterComponent(Component):
    display_name = "DataFrame AML.ID Search"
    description = "Retrieve ATLAS records based on flexible AML.ID input."
    icon = "filter"
    name = "DataFrameJSONFilter"

    inputs = [
        DataFrameInput(
            name="df",
            display_name="DataFrame",
            info="The DataFrame to filter.",
            required=True,
        ),
        StrInput(
            name="column_name",
            display_name="Column Name",
            info="Column containing AML.ID values.",
            required=True,
        ),
        DataInput(
            name="ids",
            display_name="AML.IDs",
            info=(
                "AML.IDs as a string, comma/newline separated list, JSON list, "
                "Python list, or JSON object containing an `ids` list."
            ),
            tool_mode=True,
            required=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Filtered DataFrame",
            name="output",
            method="filter_rows",
        )
    ]

    def _unwrap_value(self, value: Any) -> Any:
        """Extract useful content from Langflow Data-like objects."""
        if isinstance(value, Data):
            if isinstance(value.data, dict):
                return value.data
            return value.data

        data = getattr(value, "data", None)
        if data is not None:
            return data

        text = getattr(value, "text", None)
        if isinstance(text, str) and text.strip():
            return text

        return value

    def _parse_string_ids(self, value: str) -> list[Any]:
        """Parse IDs from a flexible string input."""
        stripped_value = value.strip()
        if not stripped_value:
            return []

        # Try JSON first:
        # ["AML.001", "AML.002"]
        # {"ids": ["AML.001", "AML.002"]}
        try:
            parsed_value = json.loads(stripped_value)
            return self._extract_ids(parsed_value)
        except json.JSONDecodeError:
            pass

        # Try Python literal syntax:
        # ['AML.001', 'AML.002']
        # ("AML.001", "AML.002")
        try:
            parsed_value = ast.literal_eval(stripped_value)
            if isinstance(parsed_value, (list, tuple, set, dict, str)):
                return self._extract_ids(parsed_value)
        except (ValueError, SyntaxError):
            pass

        # Fallback: split by common separators.
        # Supports:
        # AML.001 AML.002
        # AML.001, AML.002
        # AML.001; AML.002
        # AML.001
        # AML.002
        return [
            part.strip().strip("\"'")
            for part in re.split(r"[,;\n\r\t ]+", stripped_value)
            if part.strip().strip("\"'")
        ]

    def _extract_ids(self, value: Any) -> list[Any]:
        """Extract a raw list of IDs from supported input shapes."""
        value = self._unwrap_value(value)

        if value is None:
            return []

        if isinstance(value, dict):
            # Prefer an explicit `ids` key.
            if "ids" in value:
                return self._extract_ids(value["ids"])

            # Helpful aliases, in case the upstream tool names the key differently.
            for key in ("aml_ids", "amlIDs", "AML.IDs", "AML_IDs"):
                if key in value:
                    return self._extract_ids(value[key])

            raise ValueError(
                "ID object must contain an `ids` list or supported AML.ID alias."
            )

        if isinstance(value, str):
            return self._parse_string_ids(value)

        if isinstance(value, (list, tuple, set)):
            return list(value)

        raise ValueError(
            "IDs must be provided as a string, list, or object containing an `ids` list."
        )

    def _normalize_ids(self, value: Any) -> list[str]:
        raw_ids = self._extract_ids(value)

        normalized_ids: list[str] = []
        seen: set[str] = set()

        for id_value in raw_ids:
            if id_value is None:
                continue

            if not isinstance(id_value, str):
                id_value = str(id_value)

            stripped_id = id_value.strip().strip("\"'").lower()

            if stripped_id and stripped_id not in seen:
                normalized_ids.append(stripped_id)
                seen.add(stripped_id)

        return normalized_ids

    def run_tool(self, column_name: str, ids: Any) -> str:
        self.column_name = column_name
        self.ids = ids

        df_result = self.filter_rows()

        if isinstance(df_result, pd.DataFrame):
            return df_result.to_markdown()

        return str(df_result)

    def filter_rows(self) -> DataFrame:
        try:
            df = self.df.copy()
            ids = self._normalize_ids(self.ids)

            if not ids:
                return DataFrame(df.iloc[0:0])

            if self.column_name not in df.columns:
                raise ValueError(f"Column `{self.column_name}` does not exist.")

            column = df[self.column_name].astype(str).str.strip().str.lower()
            mask = column.isin(ids)

            return DataFrame(df[mask])

        except Exception as e:
            logger.error(f"DataFrame AML.ID search failed: {e}")
            raise
